#include <iostream>

struct Fallo {
    int etapa;
};
class Marca {
public:
    Marca() { std::cout << "Marca+|"; }
    ~Marca() { std::cout << "Marca-|"; }
};
class Preparado {
public:
    Preparado(int valor, int modo) : marca_{}, valor_{valor} {
        std::cout << "Destino|";
        if (modo == 1) { throw Fallo{1}; }
        std::cout << "DestinoListo|";
    }
    explicit Preparado(int modo) : Preparado{6, modo} {
        std::cout << "Delegado|";
        if (modo == 2) { throw Fallo{2}; }
        std::cout << "DelegadoListo|";
    }
    ~Preparado() { std::cout << "Objeto-|"; }
    int valor() const { return valor_; }
private:
    Marca marca_;
    int valor_;
};
int main() {
    try {
        Preparado dato{0};
        std::cout << "Uso:" << dato.valor() << '|';
    } catch (const Fallo& error) {
        std::cout << "Captura:" << error.etapa << '|';
    }
    std::cout << "Fin";
    return 0;
}

