    explicit Tramo(int fin) : Tramo(0, fin) {
        std::cout << "DesdeCero|";
    }

    Tramo() : Tramo(0) {
        std::cout << "Vacio|";
    }

    ~Tramo() { std::cout << "Retirado|"; }

