#include <iostream>
#include <stdexcept>

class Tramo {
public:
    Tramo(int inicio, int fin) : inicio_{inicio}, fin_{fin} {
        if (fin_ < inicio_) {
            throw std::invalid_argument("orden");
        }
        std::cout << "Preparado|";
    }

    explicit Tramo(int fin) : Tramo(0, fin) {
        std::cout << "DesdeCero|";
    }

    Tramo() : Tramo(0) {
        std::cout << "Vacio|";
    }

    ~Tramo() { std::cout << "Retirado|"; }

    void escribir(std::ostream& salida) const {
        salida << '[' << inicio_ << ',' << fin_ << "]|";
    }

private:
    const int inicio_;
    const int fin_;
};
int main() {
    {
        Tramo anterior{-4, -1};
        try {
            Tramo intento{-2};
            intento.escribir(std::cout);
        } catch (const std::invalid_argument&) {
            std::cout << "Capturado|";
        }
        anterior.escribir(std::cout);
    }
    return 0;
}
